# }
# Пример вывода
# Группировка по категориям:
# {
#  'работа': ['task1', 'task4'],
#  'учёба': ['task2', 'task5'],
#  'развлечения': ['task3']
# }
import collections
tasks = {
 "task1": "работа",
 "task2": "учёба",
 "task3": "развлечения",
 "task4": "работа",
 "task5": "учёба"
}

def task(sl_task):
    new_task = {}
    for key, value in sl_task.items():
        if value not in new_task:
            new_task[value] = [key]
        else:
            new_task[value].append(key)
    return new_task

print(task(tasks))

